import sys
sys.path.insert(0,'evaluations/spider2/adr0007/independent-recompute-35/lanes/D')
from ops import *
id='local056'
begin(id,'客户，customer.customer_id','Which customer', '''# 独立题解（揭示Gold前）
原题："Which customer has the highest average monthly change in payment amounts? Provide the customer's full name."
题面没有定义monthly change为金额差还是百分比、正负差还是绝对差，也没有规定缺月。业务文档为空。
我的主解释：每位客户先按payment_date的年-月汇总payment.amount，再按时间排序，对相邻有付款月份求有符号金额差（本月减上月），平均这些差。第一期无差而非0。不填补无观测月份。最高者保留全部并列，按customer_id确定实体后输出姓名。
理由：amounts指金额，change没有rate/absolute；月总额体现该月支付规模。数据库跨度、空值、间隔月和备选（月均交易金额、绝对差、百分比、补零）实际探索，披露无法由题面裁决的部分。
''')
query(id,'02-profile',"SELECT strftime('%Y-%m',payment_date) month, COUNT(*) payments, COUNT(DISTINCT customer_id) customers,SUM(amount) total,MIN(amount) min_amount,MAX(amount) max_amount FROM payment GROUP BY 1 ORDER BY 1")
base="""WITH m AS (SELECT customer_id,strftime('%Y-%m',payment_date) month,SUM(amount) total,AVG(amount) mean FROM payment GROUP BY 1,2),d AS (SELECT *,LAG(total) OVER(PARTITION BY customer_id ORDER BY month) prev,LAG(mean) OVER(PARTITION BY customer_id ORDER BY month) prev_mean FROM m),s AS (SELECT customer_id,COUNT(prev) n,AVG(total-prev) signed_change,AVG(ABS(total-prev)) absolute_change,AVG((total-prev)*1.0/NULLIF(prev,0)) rate,AVG(mean-prev_mean) mean_change FROM d GROUP BY 1) """
query(id,'03-top-signed',base+"SELECT s.*,c.first_name||' '||c.last_name name FROM s JOIN customer c USING(customer_id) ORDER BY signed_change DESC LIMIT 10")
query(id,'04-alternatives',base+"SELECT 'absolute' variant,s.customer_id,c.first_name||' '||c.last_name name,absolute_change metric FROM s JOIN customer c USING(customer_id) WHERE absolute_change=(SELECT MAX(absolute_change) FROM s) UNION ALL SELECT 'rate',s.customer_id,c.first_name||' '||c.last_name,rate FROM s JOIN customer c USING(customer_id) WHERE rate=(SELECT MAX(rate) FROM s) UNION ALL SELECT 'monthly_average',s.customer_id,c.first_name||' '||c.last_name,mean_change FROM s JOIN customer c USING(customer_id) WHERE mean_change=(SELECT MAX(mean_change) FROM s)")
query(id,'05-calendar-zero',"WITH RECURSIVE months(month) AS (SELECT date(MIN(payment_date),'start of month') FROM payment UNION ALL SELECT date(month,'+1 month') FROM months WHERE month<(SELECT date(MAX(payment_date),'start of month') FROM payment)), m AS(SELECT c.customer_id,month,COALESCE(SUM(p.amount),0) total FROM customer c CROSS JOIN months LEFT JOIN payment p ON p.customer_id=c.customer_id AND date(p.payment_date,'start of month')=month GROUP BY 1,2),d AS(SELECT *,LAG(total) OVER(PARTITION BY customer_id ORDER BY month) prev FROM m),s AS(SELECT customer_id,AVG(total-prev) metric FROM d GROUP BY 1) SELECT s.*,c.first_name||' '||c.last_name name FROM s JOIN customer c USING(customer_id) ORDER BY metric DESC LIMIT 5")
query(id,'06-winner-months',"SELECT customer_id,strftime('%Y-%m',payment_date) month,SUM(amount) total,COUNT(*) payments FROM payment WHERE customer_id IN (SELECT customer_id FROM ("+base+"SELECT customer_id FROM s ORDER BY signed_change DESC LIMIT 3)) GROUP BY 1,2 ORDER BY 1,2")
serialize(id,'至少两个有付款月份的客户；无可定义差分的客户排除',[], '全部payment_date，年-月排序；缺月不补零', '每客户月总付款金额SUM(amount)，相邻观测月本月总额减前月总额，对非首期差分算AVG；取最大平均差', ['customer_id'], {'n':1,'orderBy':[{'column':'signed_change','direction':'desc'}]}, {'rowMode':'full','columns':['full_name']}, {'measure.countGrain':assumed('客户的相邻有付款月份差分'),'measure.denominator':assumed('每客户月份数减1；不足2期排除'),'population.missing':assumed('不补零；相邻有付款月份')})
finish(id,base+"SELECT c.first_name||' '||c.last_name full_name FROM s JOIN customer c USING(customer_id) WHERE signed_change=(SELECT MAX(signed_change) FROM s)",{'algorithm':'monthly sums -> signed observed-month lag differences -> customer average -> all maxima','assumptions':['不补零','金额差非变化率','月总额非月交易平均额'],'limitations':['题面未定义change；备选已实际计算']})
